SELECT category, COUNT(*) AS product_count
FROM products
GROUP BY category;

BEGIN;
UPDATE orders SET status = 'cancelled' WHERE id = 3;
UPDATE products
SET stock = stock + (
  SELECT SUM(quantity) FROM order_items
  WHERE order_id = 3 AND product_id = products.id
)
WHERE id IN (SELECT product_id FROM order_items WHERE order_id = 3);
COMMIT;

SELECT (SELECT status FROM orders WHERE id = 3) AS order_status, id, stock
FROM products ORDER BY id;

CREATE INDEX idx_orders_customer_id ON orders(customer_id);
EXPLAIN QUERY PLAN
SELECT * FROM orders WHERE customer_id = 1;
